// Minimal validation + normalisation.
// Expect a shared secret header: x-bsmb-token.

const token = ($json?.headers?.['x-bsmb-token'] || $json?.headers?.['X-BSMB-Token'] || '').toString();
const expected = $env.BSMB_EVENT_TOKEN || '';
if (expected && token !== expected) {
  throw new Error('unauthorized');
}

const body = $json.body ?? $json;

function asIso(v){
  try { return new Date(v || Date.now()).toISOString(); } catch { return new Date().toISOString(); }
}

const ev = {
  ts: asIso(body.ts),
  source: (body.source || 'unknown').toString(),
  type: (body.type || 'info').toString(),
  severity: (body.severity || 'info').toString(),
  objective: body.objective || null,
  title: (body.title || 'Untitled event').toString().slice(0,160),
  detail: (body.detail || '').toString().slice(0,2000),
  links: Array.isArray(body.links) ? body.links.slice(0,10) : [],
  meta: typeof body.meta === 'object' && body.meta ? body.meta : {}
};

return [{ json: ev }];
